import { z } from "zod";
import { prisma } from "../lib/prisma.js";
import { dueDateFromTerms } from "../domain.js";
import { HttpError } from "../middleware/error-handler.js";
const send = (res, value, status = 200) => res.status(status).json(value);
const userId = (req) => req.userId;
const stages = ["Pitched", "Negotiating", "Signed", "In progress", "Delivered", "Invoiced", "Paid"];
const dealInput = z.object({ title: z.string().min(1), clientName: z.string().min(1), contactName: z.string().optional(), contactEmail: z.string().email().optional().or(z.literal("")), amountCents: z.number().int().nonnegative(), currency: z.string().length(3).default("USD"), stage: z.enum(stages).default("Pitched"), termsDays: z.number().int().positive().default(30), usageRightsText: z.string().optional(), usageRightsExpiresOn: z.string().nullable().optional(), notes: z.string().optional(), source: z.enum(["manual", "ai_paste"]).default("manual"), deliverables: z.array(z.object({ title: z.string().min(1), dueOn: z.string().nullable().optional() })).default([]) });
export async function listDeals(req, res) { return send(res, await prisma.deal.findMany({ where: { userId: userId(req), deletedAt: null }, include: { client: true, deliverables: true, invoices: { where: { deletedAt: null } } }, orderBy: { createdAt: "desc" } })); }
export async function createDeal(req, res) { const d = dealInput.parse(req.body); const uid = userId(req); const client = await prisma.client.create({ data: { userId: uid, name: d.clientName, contactName: d.contactName, contactEmail: d.contactEmail || null } }); const deal = await prisma.deal.create({ data: { userId: uid, clientId: client.id, title: d.title, amountCents: d.amountCents, currency: d.currency.toUpperCase(), stage: d.stage, termsDays: d.termsDays, usageRightsText: d.usageRightsText, usageRightsExpiresOn: d.usageRightsExpiresOn ? new Date(d.usageRightsExpiresOn) : null, notes: d.notes, source: d.source, deliverables: { create: d.deliverables.map(x => ({ title: x.title, dueOn: x.dueOn ? new Date(x.dueOn) : null })) }, activities: { create: { userId: uid, type: "deal_created", message: "Deal added" } } }, include: { client: true, deliverables: true } }); return send(res, deal, 201); }
export async function getDeal(req, res) { const deal = await prisma.deal.findFirst({ where: { id: String(req.params.id), userId: userId(req), deletedAt: null }, include: { client: true, deliverables: { orderBy: { dueOn: "asc" } }, invoices: { where: { deletedAt: null } }, focusSessions: { where: { endedAt: { not: null } }, select: { durationSecs: true } }, docs: { select: { id: true, title: true, updatedAt: true }, orderBy: { updatedAt: "desc" } } } }); if (!deal)
    throw new HttpError(404, "Deal not found."); return send(res, { ...deal, focusSeconds: deal.focusSessions.reduce((s, x) => s + (x.durationSecs ?? 0), 0) }); }
const invoiceInput = z.object({ dealId: z.string().optional(), clientId: z.string().optional(), clientName: z.string().optional(), number: z.string().min(1), issueDate: z.string(), dueDate: z.string().optional(), termsDays: z.number().int().positive().default(30), currency: z.string().length(3).default("USD"), items: z.array(z.object({ description: z.string().min(1), quantity: z.number().positive(), unitCents: z.number().int().nonnegative() })).min(1), paymentInstructions: z.string().optional() });
export async function listInvoices(req, res) { return send(res, await prisma.invoice.findMany({ where: { userId: userId(req), deletedAt: null }, include: { client: true, items: true }, orderBy: { issueDate: "desc" } })); }
export async function createInvoice(req, res) { const d = invoiceInput.parse(req.body); const uid = userId(req); let clientId = d.clientId; if (clientId && !await prisma.client.findFirst({ where: { id: clientId, userId: uid } }))
    throw new HttpError(404, "Client not found."); if (d.dealId && !await prisma.deal.findFirst({ where: { id: d.dealId, userId: uid, deletedAt: null } }))
    throw new HttpError(404, "Deal not found."); if (!clientId && d.clientName)
    clientId = (await prisma.client.create({ data: { userId: uid, name: d.clientName } })).id; const profile = await prisma.profile.findUnique({ where: { userId: uid } }); const issueDate = new Date(d.issueDate); const dueDate = d.dueDate ? new Date(d.dueDate) : dueDateFromTerms(issueDate, d.termsDays); const totalCents = d.items.reduce((s, x) => s + Math.round(x.quantity * x.unitCents), 0); const invoice = await prisma.invoice.create({ data: { userId: uid, dealId: d.dealId, clientId, number: d.number, issueDate, dueDate, currency: d.currency.toUpperCase(), totalCents, paymentInstructionsSnapshot: d.paymentInstructions ?? profile?.paymentInstructions, items: { create: d.items }, activities: { create: { userId: uid, type: "invoice_created", message: "Invoice draft created" } } }, include: { client: true, items: true } }); return send(res, invoice, 201); }
const docSchema = z.object({ title: z.string().trim().min(1).max(180), content: z.object({ type: z.literal("doc"), content: z.array(z.unknown()).max(1000) }), template: z.string().max(40).nullable().optional(), dealId: z.string().nullable().optional(), clientId: z.string().nullable().optional() });
export async function listDocs(req, res) { const uid = userId(req); const q = String(req.query.q ?? "").trim().toLowerCase(); const docs = await prisma.doc.findMany({ where: { userId: uid }, include: { deal: { select: { id: true, title: true } }, client: { select: { id: true, name: true } } }, orderBy: { updatedAt: "desc" }, take: 200 }); return send(res, { docs: (q ? docs.filter(d => `${d.title} ${JSON.stringify(d.content)}`.toLowerCase().includes(q)) : docs).slice(0, 100) }); }
export async function createDoc(req, res) { const d = docSchema.extend({ title: z.string().trim().min(1).max(180).default("Untitled") }).parse(req.body); await checkDocRefs(userId(req), d.dealId, d.clientId); const doc = await prisma.doc.create({ data: { ...d, content: d.content, userId: userId(req), dealId: d.dealId ?? null, clientId: d.clientId ?? null } }); return send(res, { id: doc.id }, 201); }
export async function getDoc(req, res) { const doc = await prisma.doc.findFirst({ where: { id: String(req.params.id), userId: userId(req) }, include: { deal: { select: { id: true, title: true } }, client: { select: { id: true, name: true } } } }); if (!doc)
    throw new HttpError(404, "Doc not found."); return send(res, doc); }
export async function updateDoc(req, res) { const d = docSchema.parse(req.body); const existing = await prisma.doc.findFirst({ where: { id: String(req.params.id), userId: userId(req) } }); if (!existing)
    throw new HttpError(404, "Doc not found."); await checkDocRefs(userId(req), d.dealId, d.clientId); await prisma.doc.update({ where: { id: existing.id }, data: { ...d, content: d.content, dealId: d.dealId ?? null, clientId: d.clientId ?? null } }); return send(res, { ok: true, updatedAt: new Date() }); }
export async function deleteDoc(req, res) { const existing = await prisma.doc.findFirst({ where: { id: String(req.params.id), userId: userId(req) } }); if (!existing)
    throw new HttpError(404, "Doc not found."); await prisma.doc.delete({ where: { id: existing.id } }); return send(res, { ok: true }); }
async function checkDocRefs(uid, dealId, clientId) { if (dealId && !await prisma.deal.findFirst({ where: { id: dealId, userId: uid, deletedAt: null } }))
    throw new HttpError(404, "Deal not found."); if (clientId && !await prisma.client.findFirst({ where: { id: clientId, userId: uid, deletedAt: null } }))
    throw new HttpError(404, "Client not found."); }
export async function docMentions(req, res) { const uid = userId(req); const q = String(req.query.q ?? "").trim(); const [deals, clients] = await Promise.all([prisma.deal.findMany({ where: { userId: uid, deletedAt: null, ...(q ? { title: { contains: q, mode: "insensitive" } } : {}) }, select: { id: true, title: true }, take: 50 }), prisma.client.findMany({ where: { userId: uid, deletedAt: null, ...(q ? { name: { contains: q, mode: "insensitive" } } : {}) }, select: { id: true, name: true }, take: 50 })]); return send(res, { mentions: [...deals.map(x => ({ id: x.id, label: x.title, type: "deal" })), ...clients.map(x => ({ id: x.id, label: x.name, type: "client" }))] }); }
export async function clients(req, res) { return send(res, { clients: await prisma.client.findMany({ where: { userId: userId(req), deletedAt: null }, select: { id: true, name: true }, orderBy: { name: "asc" } }) }); }
export async function today(req, res) { const uid = userId(req); const now = new Date(); const week = new Date(now); week.setDate(week.getDate() + 7); const pitchThreshold = new Date(now); pitchThreshold.setDate(pitchThreshold.getDate() - 3); const [tasks, deliverables, invoices, pitches, deals] = await Promise.all([prisma.task.findMany({ where: { userId: uid, completedAt: null }, include: { deal: { select: { id: true, title: true, amountCents: true, currency: true } } }, orderBy: [{ dueOn: "asc" }, { createdAt: "asc" }], take: 20 }), prisma.deliverable.findMany({ where: { doneAt: null, dueOn: { lte: week }, deal: { userId: uid, deletedAt: null } }, include: { deal: { select: { id: true, title: true, amountCents: true, currency: true } } }, orderBy: { dueOn: "asc" }, take: 20 }), prisma.invoice.findMany({ where: { userId: uid, deletedAt: null, OR: [{ status: "Draft" }, { status: "Sent", dueDate: { lt: now } }] }, include: { client: true, deal: { select: { id: true, title: true } } }, orderBy: { dueDate: "asc" }, take: 20 }), prisma.deal.findMany({ where: { userId: uid, deletedAt: null, stage: "Pitched", createdAt: { lte: pitchThreshold } }, include: { client: true }, orderBy: { createdAt: "asc" }, take: 10 }), prisma.deal.findMany({ where: { userId: uid, deletedAt: null }, select: { id: true, title: true }, orderBy: { title: "asc" } })]); const p = []; for (const t of tasks)
    p.push({ id: `task:${t.id}`, kind: "task", title: t.title, dealTitle: t.deal?.title ?? "Personal task", dueOn: t.dueOn?.toISOString() ?? null, amountCents: t.deal?.amountCents ?? 0, currency: t.deal?.currency ?? "USD" }); for (const x of deliverables)
    p.push({ id: `deliverable:${x.id}`, kind: "deliverable", title: x.title, dealTitle: x.deal.title, dueOn: x.dueOn?.toISOString() ?? null, amountCents: x.deal.amountCents, currency: x.deal.currency }); for (const x of invoices)
    p.push({ id: `invoice:${x.id}`, kind: x.status === "Draft" ? "draft_invoice" : "overdue_invoice", title: x.status === "Draft" ? `Send invoice ${x.number}` : `Follow up on invoice ${x.number}`, dealTitle: x.deal?.title ?? x.client?.name ?? "Invoice", dueOn: x.dueDate.toISOString(), amountCents: x.totalCents, currency: x.currency }); for (const x of pitches)
    p.push({ id: `pitch:${x.id}`, kind: "pitch", title: `Follow up on your pitch to ${x.client?.name ?? x.title}`, dealTitle: x.title, dueOn: x.createdAt.toISOString(), amountCents: x.amountCents, currency: x.currency }); const rank = { overdue_invoice: 0, deliverable: 1, draft_invoice: 2, task: 3, pitch: 4 }; p.sort((a, b) => (rank[a.kind] ?? 5) - (rank[b.kind] ?? 5) || (a.dueOn ? Date.parse(a.dueOn) : Infinity) - (b.dueOn ? Date.parse(b.dueOn) : Infinity)); return send(res, { priorities: p.slice(0, 20), deals, tasks: tasks.map(t => ({ id: t.id, title: t.title, dueOn: t.dueOn?.toISOString() ?? null, dealId: t.dealId, dealTitle: t.deal?.title ?? null })) }); }
export async function createTask(req, res) { const d = z.object({ title: z.string().trim().min(1).max(180), dealId: z.string().nullable().optional(), dueOn: z.string().datetime().nullable().optional() }).parse(req.body); if (d.dealId && !await prisma.deal.findFirst({ where: { id: d.dealId, userId: userId(req), deletedAt: null } }))
    throw new HttpError(404, "That deal was not found."); return send(res, await prisma.task.create({ data: { userId: userId(req), title: d.title, dealId: d.dealId ?? null, dueOn: d.dueOn ? new Date(d.dueOn) : null } }), 201); }
export async function updateTask(req, res) { const d = z.object({ completed: z.boolean() }).parse(req.body); const task = await prisma.task.findFirst({ where: { id: String(req.params.id), userId: userId(req) } }); if (!task)
    throw new HttpError(404, "Task not found."); return send(res, await prisma.task.update({ where: { id: task.id }, data: { completedAt: d.completed ? new Date() : null } })); }
